// Theme switches. One obvious place for app-wide behaviour (ADR 0004: font scaling off by default).
export const config = {
  /** Respect the OS font-size setting. Off by default; turn on for apps serving users who need larger text. */
  fontScaling: false,
  /** Light/dark before the user picks one: follow the system, or force a Scheme. */
  defaultScheme: "system" as "system" | "light" | "dark",
  /** Scale = shorter screen side ÷ baseline, clamped to [min, max]. */
  scale: { baseline: 390, min: 0.85, max: 1.25 },
  /** Light haptic tick on selection controls (Switch, Checkbox, Radio, SegmentedTabs, Chip, Slider). */
  haptics: true,
} as const;

export type ThemeConfig = typeof config;

export { colors, type ColorRole, type Colors } from "./colors";
export { config } from "./config";
export { useNavigationTheme } from "./navigation";
export {
  ThemeProvider,
  createStyles,
  resetStyles,
  useTheme,
  type Scheme,
  type Theme,
} from "./provider";
export { computeScale, scaleTokens, scaleValue } from "./scale";
export { useSchemeStore, type SchemePreference } from "./scheme-store";
export * as tokens from "./tokens";

import { useTheme } from "./provider";

/**
 * Expo Router / React Navigation theme derived from the Theme, so headers, tab bars and
 * drawers match the Preset. Pass it to Expo Router's ThemeProvider in the root Layout.
 */
export function useNavigationTheme() {
  const t = useTheme();
  const font = (fontFamily: string) => ({ fontFamily, fontWeight: "normal" as const });
  return {
    dark: t.scheme === "dark",
    colors: {
      primary: t.colors.primary,
      background: t.colors.background,
      card: t.colors.card,
      text: t.colors.foreground,
      border: t.colors.border,
      notification: t.colors.destructive,
    },
    fonts: {
      regular: font(t.type.body.fontFamily ?? "System"),
      medium: font(t.type.label.fontFamily ?? "System"),
      bold: font(t.type.button.fontFamily ?? "System"),
      heavy: font(t.type.h1.fontFamily ?? "System"),
    },
  };
}

import { useFonts, type FontSource } from "expo-font";
import * as SplashScreen from "expo-splash-screen";
import { createContext, use, useEffect, useMemo, type ReactNode } from "react";
import { Appearance, StyleSheet, useColorScheme, useWindowDimensions } from "react-native";

import { colors, type Colors } from "./colors";
import { config } from "./config";
import { computeScale, scaleTokens, scaleValue, type ScaledTokens } from "./scale";
import { useSchemeStore, type SchemePreference } from "./scheme-store";
import { borderWidth, elevation, minTouchTarget, motion, opacity, radiusBase } from "./tokens";

// Keep the splash screen up until fonts and the persisted Scheme are ready, so the
// first frame is never the wrong font or the wrong Scheme.
SplashScreen.preventAutoHideAsync().catch(() => {});

export type Scheme = "light" | "dark";

export type Theme = ScaledTokens & {
  scheme: Scheme;
  schemePreference: SchemePreference;
  setScheme: (scheme: SchemePreference) => void;
  scale: number;
  /** Scale a one-off literal the same way Tokens are scaled. */
  scaleValue: (value: number) => number;
  colors: Colors;
  elevation: Record<"sm" | "md" | "lg", string>;
  borderWidth: typeof borderWidth;
  motion: typeof motion;
  opacity: typeof opacity;
  minTouchTarget: number;
  config: typeof config;
};

const ThemeContext = createContext<Theme | null>(null);

type ThemeProviderProps = {
  children: ReactNode;
  /** Force a Scheme for this subtree (e.g. previews). Normally omitted: the user's persisted choice applies. */
  scheme?: SchemePreference;
  /** Font faces to load (PostScript name → asset). A no-op for faces already embedded by the expo-font plugin. */
  fonts?: Record<string, FontSource>;
};

export function ThemeProvider({ children, scheme: forced, fonts = {} }: ThemeProviderProps) {
  const preference = useSchemeStore((s) => s.scheme);
  const hydrated = useSchemeStore((s) => s.hydrated);
  const setPreference = useSchemeStore((s) => s.setScheme);
  const system = useColorScheme();
  const { width, height } = useWindowDimensions();
  const [fontsLoaded, fontError] = useFonts(fonts);

  const schemePreference = forced ?? preference;
  const resolved: Scheme =
    schemePreference === "system" ? (system === "dark" ? "dark" : "light") : schemePreference;
  const scale = computeScale(width, height);
  const noFonts = Object.keys(fonts).length === 0;
  const ready = hydrated && (noFonts || fontsLoaded || fontError != null);

  useEffect(() => {
    // Native chrome (keyboard, status bar, Switch) follows the app's Scheme, not just our Components.
    Appearance.setColorScheme(preference === "system" ? "unspecified" : preference);
  }, [preference]);

  useEffect(() => {
    if (ready) SplashScreen.hideAsync().catch(() => {});
  }, [ready]);

  const theme = useMemo<Theme>(
    () => ({
      ...scaleTokens(scale, { radiusBase }),
      scheme: resolved,
      schemePreference,
      setScheme: setPreference,
      scale,
      scaleValue: (v) => scaleValue(v, scale),
      colors: colors[resolved],
      elevation: elevation[resolved],
      borderWidth,
      motion,
      opacity,
      minTouchTarget,
      config,
    }),
    [scale, resolved, schemePreference, setPreference],
  );

  if (!ready) return null;
  return <ThemeContext value={theme}>{children}</ThemeContext>;
}

export function useTheme(): Theme {
  const theme = use(ThemeContext);
  if (!theme) {
    throw new Error(
      "useTheme() must be used inside <ThemeProvider> from @/theme. Wrap your app with it in app/_layout.tsx.",
    );
  }
  return theme;
}

/**
 * Build a Component's styles from the Theme. StyleSheet.create runs once per (Scale, Scheme)
 * and is cached, never per render.
 */
const styleCaches = new Set<Map<string, unknown>>();

/** Drop every cached Component style, so the next render rebuilds them (e.g. after switching Style in the Showcase App). */
export function resetStyles(): void {
  for (const cache of styleCaches) cache.clear();
}

export function createStyles<T extends StyleSheet.NamedStyles<T>>(factory: (theme: Theme) => T) {
  const cache = new Map<string, T>();
  styleCaches.add(cache);
  return function useStyles(): T {
    const theme = useTheme();
    const key = `${theme.scale}|${theme.scheme}`;
    let styles = cache.get(key);
    if (!styles) {
      styles = StyleSheet.create(factory(theme));
      cache.set(key, styles);
    }
    return styles;
  };
}

import { PixelRatio } from "react-native";

import { config } from "./config";
import {
  controlHeight,
  fonts,
  iconSize,
  radius,
  spacing,
  typeRamp,
  type TextVariant,
  type TypeStyle,
} from "./tokens";

/** Scale = shorter screen side ÷ baseline, clamped. The shorter side keeps it stable on rotation. */
export function computeScale(width: number, height: number, cfg = config.scale): number {
  const shorter = Math.min(width, height);
  return Math.min(cfg.max, Math.max(cfg.min, shorter / cfg.baseline));
}

/** Apply Scale to one base value, rounded to the nearest physical pixel. */
export function scaleValue(value: number, scale: number): number {
  return PixelRatio.roundToNearestPixel(value * scale);
}

function mapValues<T extends Record<string, number>>(obj: T, fn: (v: number) => number) {
  return Object.fromEntries(Object.entries(obj).map(([k, v]) => [k, fn(v)])) as {
    [K in keyof T]: number;
  };
}

/**
 * Pre-scaled Tokens. Scales spacing, radius (except `full`), control heights, icon sizes and text;
 * never the touch target, borders, shadows, motion or opacity.
 */
export function scaleTokens(scale: number, base = { radiusBase: undefined as number | undefined }) {
  const s = (v: number) => scaleValue(v, scale);
  const r = radius(base.radiusBase);
  const type = Object.fromEntries(
    (Object.keys(typeRamp) as TextVariant[]).map((variant) => {
      const step = typeRamp[variant];
      const family = fonts[step.role][step.face];
      const style: TypeStyle = {
        fontFamily: family,
        fontSize: s(step.size),
        lineHeight: s(step.lineHeight),
        letterSpacing: (step.tracking + fonts.trackingOffset[step.role]) * scale,
      };
      return [variant, style];
    }),
  ) as Record<TextVariant, TypeStyle>;

  return {
    spacing: mapValues(spacing, s),
    radius: {
      ...mapValues({ sm: r.sm, md: r.md, lg: r.lg, xl: r.xl, "2xl": r["2xl"] }, s),
      full: r.full,
    },
    controlHeight: mapValues(controlHeight, s),
    iconSize: mapValues(iconSize, s),
    type,
  };
}

export type ScaledTokens = ReturnType<typeof scaleTokens>;

import AsyncStorage from "@react-native-async-storage/async-storage";
import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";

import { config } from "./config";

export type SchemePreference = "system" | "light" | "dark";

type SchemeState = {
  scheme: SchemePreference;
  hydrated: boolean;
  setScheme: (scheme: SchemePreference) => void;
};

/**
 * The user's light/dark choice, persisted under `nativecn-theme` (Design System ADR 0001).
 * Only the Scheme is persisted: the Preset is a file and Scale comes from the screen.
 */
export const useSchemeStore = create<SchemeState>()(
  persist(
    (set) => ({
      scheme: config.defaultScheme,
      hydrated: false,
      setScheme: (scheme) => set({ scheme }),
    }),
    {
      name: "nativecn-theme",
      storage: createJSONStorage(() => AsyncStorage),
      partialize: (state) => ({ scheme: state.scheme }),
      onRehydrateStorage: () => () => useSchemeStore.setState({ hydrated: true }),
    },
  ),
);

import type { TextStyle } from "react-native";

// Base Token values (before Scale). See "Token set for 0.1" and "Scale mechanics".

export const spacing = {
  0: 0,
  0.5: 2,
  1: 4,
  2: 8,
  3: 12,
  4: 16,
  5: 20,
  6: 24,
  8: 32,
  10: 40,
  12: 48,
  16: 64,
} as const;

/** Every radius step derives from one base, which the Preset's Radius setting overrides. */
export const radiusBase = 10;
export const radius = (base: number = radiusBase) =>
  ({
    sm: base - 4,
    md: base - 2,
    lg: base,
    xl: base + 4,
    "2xl": base + 8,
    full: 9999,
  }) as const;

/** Body and Heading Font faces (PostScript names). `create`/`init` rewrite these from the Preset. */
export const fonts = {
  body: {
    regular: "Inter-Regular",
    medium: "Inter-Medium",
    semibold: "Inter-SemiBold",
    bold: "Inter-Bold",
  },
  heading: {
    regular: "Inter-Regular",
    medium: "Inter-Medium",
    semibold: "Inter-SemiBold",
    bold: "Inter-Bold",
  },
  /** Letter-spacing correction for the chosen Body/Heading Font (Inter is the baseline, 0). */
  trackingOffset: { body: 0, heading: 0 },
} as const;

type Face = keyof typeof fonts.body;
type Step = {
  size: number;
  lineHeight: number;
  face: Face;
  tracking: number;
  role: "body" | "heading";
};

/** Text Variants (the type ramp). Weight is chosen by face, never fontWeight. */
export const typeRamp = {
  display: { size: 36, lineHeight: 40, face: "bold", tracking: -0.8, role: "heading" },
  h1: { size: 30, lineHeight: 36, face: "bold", tracking: -0.6, role: "heading" },
  h2: { size: 24, lineHeight: 32, face: "semibold", tracking: -0.4, role: "heading" },
  h3: { size: 20, lineHeight: 28, face: "semibold", tracking: -0.2, role: "heading" },
  h4: { size: 17, lineHeight: 24, face: "semibold", tracking: 0, role: "heading" },
  lead: { size: 18, lineHeight: 28, face: "regular", tracking: 0, role: "body" },
  body: { size: 16, lineHeight: 24, face: "regular", tracking: 0, role: "body" },
  label: { size: 14, lineHeight: 20, face: "medium", tracking: 0, role: "body" },
  small: { size: 14, lineHeight: 20, face: "regular", tracking: 0, role: "body" },
  caption: { size: 12, lineHeight: 16, face: "regular", tracking: 0, role: "body" },
  button: { size: 15, lineHeight: 20, face: "semibold", tracking: 0, role: "body" },
} as const satisfies Record<string, Step>;

export type TextVariant = keyof typeof typeRamp;
export type TypeStyle = Pick<TextStyle, "fontSize" | "lineHeight" | "letterSpacing" | "fontFamily">;

export const controlHeight = { sm: 36, md: 44, lg: 52 } as const;
export const iconSize = { sm: 16, md: 20, lg: 24 } as const;

/** Not scaled: an accessibility floor (48 on both platforms). */
export const minTouchTarget = 48;

export const borderWidth = { default: 1, hairline: "hairline" as const };

/** boxShadow strings per Scheme; exact values are tuned during the build. */
export const elevation = {
  light: {
    sm: "0 1px 2px rgba(0, 0, 0, 0.06)",
    md: "0 4px 12px rgba(0, 0, 0, 0.08)",
    lg: "0 8px 24px rgba(0, 0, 0, 0.14)",
  },
  dark: {
    sm: "0 1px 2px rgba(0, 0, 0, 0.6)",
    md: "0 4px 12px rgba(0, 0, 0, 0.6)",
    lg: "0 8px 24px rgba(0, 0, 0, 0.7)",
  },
} as const;

export const motion = {
  duration: { fast: 150, base: 250, slow: 400 },
  easing: {
    standard: [0.2, 0, 0, 1],
    enter: [0, 0, 0, 1],
    exit: [0.3, 0, 1, 1],
  },
  spring: {
    snappy: { damping: 20, stiffness: 300, mass: 1 },
    gentle: { damping: 18, stiffness: 140, mass: 1 },
  },
} as const;

export const opacity = { disabled: 0.5 } as const;
